//! SSH device hosts (the reference's `SshDeviceHost.ts`, with `runSshCommand`
//! from `@t3tools/ssh`): a machine reached over SSH whose simulators and
//! emulators an agent can use. Every remote command runs the reference's
//! shell prelude, and host work runs the reference's Node bootstrap
//! (`device_ssh.json`, generated by `scripts/update_agent_tools.py`) on the
//! host's own `node`.
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::{
    path::Path,
    process::Stdio,
    sync::{Arc, LazyLock},
    time::Duration,
};
use tokio::io::AsyncWriteExt;

static SCRIPTS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(include_str!("device_ssh.json")).expect("SSH device host scripts")
});
const DEFAULT_SSH_COMMAND_TIMEOUT: Duration = Duration::from_millis(60_000);
const MAX_SSH_ERROR_OUTPUT_LENGTH: usize = 4_000;
const NODE_MISSING: &str = "Node is missing from the non-interactive SSH PATH";

/// `SshDeviceHostConfig`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) struct SshConfig {
    pub id: String,
    pub label: String,
    pub target: String,
    pub port: Option<u16>,
    pub identity_file: Option<String>,
}

impl SshConfig {
    /// A saved `deviceHosts` entry; hosts saved before Expo hosts carry no kind.
    pub fn from_settings(value: &Value) -> Option<Self> {
        if !value["kind"].is_null() && value["kind"] != "ssh" {
            return None;
        }
        Some(Self {
            id: value["id"].as_str()?.to_owned(),
            label: value["label"].as_str()?.to_owned(),
            target: value["target"].as_str()?.to_owned(),
            port: value["port"].as_u64().and_then(|p| u16::try_from(p).ok()),
            identity_file: value["identityFile"].as_str().map(str::to_owned),
        })
    }

    fn identity_args(&self) -> Vec<String> {
        match &self.identity_file {
            Some(file) => vec!["-i".into(), file.clone()],
            None => vec![],
        }
    }

    /// The host's summary before it is probed.
    pub fn unprobed_summary(&self) -> Value {
        json!({
            "id": self.id,
            "label": self.label,
            "kind": "ssh",
            "hubInstalled": false,
            "agentDeviceInstalled": false,
            "platforms": [],
        })
    }
}

/// `ownerFor`: this server's name on the host, so two servers sharing a host
/// keep their hubs apart.
pub(super) fn owner(dir: &Path, host_id: &str) -> String {
    let state_dir = dir.to_string_lossy().into_owned();
    let environment =
        std::fs::read_to_string(dir.join("environment-id")).unwrap_or(state_dir.clone());
    let digest = Sha256::digest(format!("{environment}\0{state_dir}\0{host_id}").as_bytes());
    hex::encode(digest)[..24].to_owned()
}

/// `quoteRemoteArg`.
pub(super) fn quote_remote_arg(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\"'\"'"))
}

fn environment() -> &'static str {
    SCRIPTS["environment"].as_str().unwrap_or_default()
}

/// `remoteDeviceScript(owner, mode)`.
fn bootstrap_script(owner: &str, mode: &str) -> String {
    SCRIPTS["script"]
        .as_str()
        .unwrap_or_default()
        .replace("\"{{OWNER}}\"", &json!(owner).to_string())
        .replace("\"{{MODE}}\"", &json!(mode).to_string())
}

/// `commandArgs`: a remote `sh -c` that starts with the reference's prelude.
pub(super) fn command_args(script: &str) -> Vec<String> {
    vec![
        "sh".into(),
        "-c".into(),
        quote_remote_arg(&format!("{}{script}", environment())),
    ]
}

/// `baseSshArgs` with batch mode on.
pub(super) fn base_ssh_args(port: Option<u16>) -> Vec<String> {
    let mut args: Vec<String> = [
        "-o",
        "BatchMode=yes",
        "-o",
        "ConnectTimeout=10",
        "-o",
        "RemoteCommand=none",
        "-o",
        "RequestTTY=no",
    ]
    .map(String::from)
    .to_vec();
    if let Some(port) = port {
        args.extend(["-p".into(), port.to_string()]);
    }
    args
}

/// `SshCommandError`.
#[derive(Clone, Debug)]
pub(super) struct SshCommandError {
    pub exit_code: Option<i32>,
    /// What the command printed, redacted and bounded.
    pub stdout: String,
    pub stderr: String,
    pub message: String,
}

/// `redactSshErrorOutput`.
fn redact(output: &str, keep_tail: bool) -> String {
    static TOKEN: LazyLock<regex::Regex> = LazyLock::new(|| {
        regex::Regex::new(
            r#"(?i)("(?:access_token|bearerToken|credential|pairingToken|token)"\s*:\s*")[^"]+(")"#,
        )
        .unwrap()
    });
    let redacted = TOKEN.replace_all(output, "${1}[redacted]${2}").into_owned();
    let length = redacted.encode_utf16().count();
    if length <= MAX_SSH_ERROR_OUTPUT_LENGTH {
        return redacted;
    }
    let units: Vec<u16> = redacted.encode_utf16().collect();
    if keep_tail {
        format!(
            "[truncated]\n{}",
            String::from_utf16_lossy(&units[length - MAX_SSH_ERROR_OUTPUT_LENGTH..])
        )
    } else {
        format!(
            "{}\n[truncated]",
            String::from_utf16_lossy(&units[..MAX_SSH_ERROR_OUTPUT_LENGTH])
        )
    }
}

/// `terminalArg` on a POSIX host.
fn terminal_arg(value: &str) -> String {
    static SAFE: LazyLock<regex::Regex> =
        LazyLock::new(|| regex::Regex::new(r"^[A-Za-z0-9_@%+=:,./-]+$").unwrap());
    if SAFE.is_match(value) {
        value.to_owned()
    } else {
        format!("'{}'", value.replace('\'', "'\\''"))
    }
}

/// `hostKeyVerificationMessage`: what to run in a terminal when ssh could not
/// verify the host key, since the app never answers host key prompts.
fn host_key_message(port: Option<u16>, host_spec: &str, stderr: &str) -> Option<String> {
    if !stderr.contains("Host key verification failed") {
        return None;
    }
    let mut command = vec!["ssh".to_owned()];
    if let Some(port) = port {
        command.extend(["-p".into(), port.to_string()]);
    }
    if host_spec.starts_with('-') {
        command.push("--".into());
    }
    command.push(host_spec.to_owned());
    let command = command
        .iter()
        .map(|arg| terminal_arg(arg))
        .collect::<Vec<_>>()
        .join(" ");
    let guidance = if stderr.contains("REMOTE HOST IDENTIFICATION HAS CHANGED") {
        format!("The host key for {host_spec} has changed since it was trusted. Only if you expect this change, remove the old key with the `ssh-keygen -R` command in the output below, run `{command}` in a terminal, check that the new host key fingerprint is the one you expect, then try again.")
    } else {
        format!("SSH could not verify the host key for {host_spec}. Run `{command}` in a terminal, check that the host key fingerprint is the one you expect, then try again.")
    };
    Some(format!("{guidance}\n\n{}", stderr.trim()))
}

/// `runSshCommand`: `ssh` to the host with the reference's options, `stdin`
/// written and closed, within `timeout`.
pub(super) async fn run_ssh(
    config: &SshConfig,
    pre_host_args: &[String],
    remote_args: &[String],
    stdin: Option<&str>,
    timeout: Option<Duration>,
    keep_tail: bool,
) -> Result<(String, String), SshCommandError> {
    let host_spec = config.target.trim();
    let mut args = base_ssh_args(config.port);
    // Cold installs need a long command budget; a lost connection must fail sooner.
    args.extend(
        [
            "-o",
            "ServerAliveInterval=15",
            "-o",
            "ServerAliveCountMax=3",
        ]
        .map(String::from),
    );
    args.extend(pre_host_args.iter().cloned());
    args.push("--".into());
    args.push(host_spec.to_owned());
    args.extend(remote_args.iter().cloned());
    let timeout = timeout.unwrap_or(DEFAULT_SSH_COMMAND_TIMEOUT);
    let mut command = crate::login_shell::tokio_command("ssh");
    command
        .args(&args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .kill_on_drop(true);
    let spawn_failed = |message: String| SshCommandError {
        exit_code: None,
        stdout: String::new(),
        stderr: String::new(),
        message,
    };
    let mut child = command
        .spawn()
        .map_err(|error| spawn_failed(error.to_string()))?;
    let input = stdin.unwrap_or_default().to_owned();
    let mut pipe = child.stdin.take();
    let writer = tokio::spawn(async move {
        if let Some(pipe) = pipe.as_mut() {
            let _ = pipe.write_all(input.as_bytes()).await;
            let _ = pipe.shutdown().await;
        }
    });
    let output = match tokio::time::timeout(timeout, child.wait_with_output()).await {
        Err(_) => {
            return Err(SshCommandError {
                exit_code: None,
                stdout: String::new(),
                stderr: String::new(),
                message: format!("SSH command timed out after {}ms.", timeout.as_millis()),
            })
        }
        Ok(Err(error)) => return Err(spawn_failed(error.to_string())),
        Ok(Ok(output)) => output,
    };
    let _ = writer.await;
    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
    let stderr = String::from_utf8_lossy(&output.stderr).into_owned();
    if !output.status.success() {
        let exit_code = output.status.code();
        let diagnostic = redact(&stdout, keep_tail);
        let message = if let Some(message) = host_key_message(config.port, host_spec, &stderr) {
            message
        } else if !stderr.trim().is_empty() {
            stderr.trim().to_owned()
        } else if !diagnostic.trim().is_empty() {
            diagnostic.trim().to_owned()
        } else {
            format!(
                "SSH command failed for {host_spec} (exit {}).",
                exit_code.unwrap_or(-1)
            )
        };
        tracing::warn!(
            target = %config.target,
            exit_code,
            stdout = %diagnostic,
            stderr = %stderr,
            "ssh.command.failed"
        );
        return Err(SshCommandError {
            exit_code,
            stdout: diagnostic,
            stderr,
            message,
        });
    }
    Ok((stdout, stderr))
}

/// Why a host step failed: the `DeviceHostError` cause the reference keeps.
#[derive(Clone, Debug)]
pub(super) enum Cause {
    Ssh(SshCommandError),
    /// `SshConnectError`: ssh refused before the bootstrap ran.
    Connect {
        reason: &'static str,
        target: String,
        detail: String,
        ssh: SshCommandError,
    },
    /// `SshWindowsHostError`, over the command's own failure.
    Windows(SshCommandError),
    /// Anything else, such as a probe result that does not parse.
    Other,
}

/// `DeviceHostError`.
#[derive(Clone, Debug)]
pub(super) struct HostError {
    pub step: String,
    pub cause: Box<Cause>,
}

impl HostError {
    /// The error as the reference encodes it in a failure's `cause` (a
    /// defect: each error's name and message, then its own cause).
    pub fn encoded(&self, host_id: &str) -> Value {
        let command =
            |ssh: &SshCommandError| json!({"name": "SshCommandError", "message": ssh.message});
        let mut encoded = json!({
            "name": "DeviceHostError",
            "message": format!("Device host {host_id} failed while {}.", self.step),
        });
        match self.cause.as_ref() {
            Cause::Ssh(ssh) => encoded["cause"] = command(ssh),
            Cause::Connect {
                reason,
                target,
                detail,
                ssh,
            } => {
                encoded["cause"] = json!({
                    "name": "SshConnectError",
                    "message": connect_message(reason, target, detail),
                    "cause": command(ssh),
                })
            }
            Cause::Windows(ssh) => {
                encoded["cause"] = json!({
                    "name": "SshWindowsHostError",
                    "message": WINDOWS_MESSAGE,
                    "cause": command(ssh),
                })
            }
            Cause::Other => {}
        }
        encoded
    }
}

/// `SshConnectError.message`.
fn connect_message(reason: &str, target: &str, detail: &str) -> String {
    let here = "the machine running this T3 Code server";
    let detail = detail.strip_suffix('.').unwrap_or(detail);
    match reason {
        "host_key_unknown" => format!("SSH encountered an untrusted host key while connecting to {target} from {here}. Connect once with ssh from there to identify the host and verify its key before accepting it."),
        "host_key_changed" => format!("SSH encountered a changed host key while connecting to {target} from {here}. Connect once with ssh from there to identify the affected host. If the change is expected, remove that host's old key with `ssh-keygen -R`, then verify and accept its new key."),
        "auth" => format!("SSH login failed while connecting to {target}: {detail}. SSH from {here} must log in without a prompt."),
        "resolve" => format!("Could not resolve the host name {target} from {here}: {detail}."),
        _ => format!("Could not reach {target} from {here}: {detail}. Check that the host is on, its SSH server is running, and the address and port are right."),
    }
}

const WINDOWS_MESSAGE: &str = "Connected over SSH, but this host runs Windows, and SSH device hosts currently need macOS or Linux. To use this machine's devices, run T3 Code on it and connect to that environment.";

/// `explainSshConnectFailure`: ssh exits 255 for its own failures.
fn explain_connect(config: &SshConfig, error: HostError) -> HostError {
    let Cause::Ssh(ssh) = error.cause.as_ref() else {
        return error;
    };
    if ssh.exit_code != Some(255) {
        return error;
    }
    static PATTERNS: LazyLock<Vec<(&'static str, regex::Regex)>> = LazyLock::new(|| {
        [
            ("host_key_changed", r"REMOTE HOST IDENTIFICATION HAS CHANGED"),
            ("host_key_unknown", r"^Host key verification failed\.$"),
            (
                "auth",
                r"^\S+: (?:Permission denied \(|No supported authentication methods)|: Too many authentication failures$",
            ),
            ("resolve", r"^ssh: Could not resolve hostname "),
            ("connect", r"^ssh: connect to host "),
        ]
        .into_iter()
        .map(|(reason, pattern)| (reason, regex::Regex::new(pattern).unwrap()))
        .collect()
    });
    let lines: Vec<&str> = ssh
        .stderr
        .split('\n')
        .map(|l| l.trim_end_matches('\r').trim())
        .collect();
    for (reason, pattern) in PATTERNS.iter() {
        if let Some(detail) = lines.iter().find(|line| pattern.is_match(line)) {
            return HostError {
                step: error.step.clone(),
                cause: Box::new(Cause::Connect {
                    reason,
                    target: config.target.clone(),
                    detail: (*detail).to_owned(),
                    ssh: ssh.clone(),
                }),
            };
        }
    }
    error
}

/// `explainWindowsHost`: a bootstrap that failed on a Windows host.
async fn explain_windows(config: &SshConfig, error: HostError) -> HostError {
    let Cause::Ssh(ssh) = error.cause.as_ref() else {
        return error;
    };
    let Some(code) = ssh.exit_code else {
        return error;
    };
    if code < 1 || (code > 254 && code != 9009) {
        return error;
    }
    let identity = config.identity_args();
    let mut windows = matches!(
        run_ssh(config, &identity, &["echo %OS% $env:OS".into()], None, Some(Duration::from_secs(15)), false).await,
        Ok((stdout, _)) if stdout.split_whitespace().any(|word| word == "Windows_NT")
    );
    if !windows {
        // Git Bash does not expand Windows shell variables, but its Node still reports win32.
        windows = matches!(
            run_ssh(
                config,
                &identity,
                &["node".into(), "-p".into(), "process.platform".into()],
                None,
                Some(Duration::from_secs(15)),
                false,
            )
            .await,
            Ok((stdout, _)) if stdout.trim() == "win32"
        );
    }
    if !windows {
        return error;
    }
    HostError {
        step: error.step,
        cause: Box::new(Cause::Windows(ssh.clone())),
    }
}

/// `bootstrap`: the reference's Node script on the host's `node`.
pub(super) async fn bootstrap(
    config: &SshConfig,
    owner: &str,
    mode: &str,
) -> Result<(String, String), HostError> {
    let timeout = if mode == "start" || mode == "agent-start" {
        Duration::from_millis(1_300_000)
    } else {
        Duration::from_millis(45_000)
    };
    run_ssh(
        config,
        &config.identity_args(),
        &command_args(&format!(
            "command -v node >/dev/null 2>&1 || {{ echo \"{NODE_MISSING}\" >&2; exit 1; }}; exec node"
        )),
        Some(&bootstrap_script(owner, mode)),
        Some(timeout),
        false,
    )
    .await
    .map_err(|error| HostError {
        step: mode.to_owned(),
        cause: Box::new(Cause::Ssh(error)),
    })
}

/// `probe`: the host's platforms and tools, as its summary.
pub(super) async fn probe(config: &SshConfig, owner: &str) -> Result<Value, HostError> {
    let (stdout, _) = match bootstrap(config, owner, "probe").await {
        Ok(output) => output,
        Err(error) => return Err(explain_windows(config, explain_connect(config, error)).await),
    };
    let reading = || HostError {
        step: "reading probe result".into(),
        cause: Box::new(Cause::Other),
    };
    let value: Value = serde_json::from_str(stdout.trim()).map_err(|error| {
        tracing::warn!(host = %config.id, %error, "Could not read the device host probe result");
        reading()
    })?;
    if !value["nodePath"].is_string() || !value["platforms"].is_array() {
        return Err(reading());
    }
    let tools = &value["tools"];
    let installed = |tool: &str| {
        tools[tool]["installedVersions"]
            .as_array()
            .is_some_and(|versions| versions.contains(&tools[tool]["requiredVersion"]))
    };
    let mut summary = json!({"id": config.id, "label": config.label, "kind": "ssh"});
    if !tools.is_null() {
        summary["tools"] = tools.clone();
    }
    summary["hubInstalled"] = json!(installed("hub"));
    summary["agentDeviceInstalled"] = json!(installed("agent"));
    summary["platforms"] = value["platforms"].clone();
    Ok(summary)
}

/// `sshProbeFailureMessage`: what a failed probe tells the user.
pub(super) fn probe_failure_message(error: &HostError) -> Option<String> {
    let (cause, windows) = match error.cause.as_ref() {
        Cause::Connect {
            reason,
            target,
            detail,
            ..
        } => return Some(connect_message(reason, target, detail)),
        Cause::Windows(ssh) => (ssh, true),
        Cause::Ssh(ssh) => (ssh, false),
        Cause::Other => return None,
    };
    let generic = "Could not connect to this host over SSH.".to_owned();
    let Some(code) = cause.exit_code else {
        return Some(generic);
    };
    if code < 1 || (code > 254 && code != 9009) {
        return Some(generic);
    }
    // Only the known bootstrap diagnostic is safe to expose as Node guidance.
    if code == 1
        && cause
            .stderr
            .split('\n')
            .any(|line| line.trim() == NODE_MISSING)
    {
        return Some("Connected over SSH, but Node is not on this host's PATH for non-interactive SSH commands.".into());
    }
    if windows {
        return Some(WINDOWS_MESSAGE.into());
    }
    Some(format!(
        "Connected over SSH, but the device host check failed (exit code {code})."
    ))
}

/// `Started`: what the bootstrap's `start` reports, with the host's ports.
#[derive(Clone, Debug)]
pub(super) struct Started {
    pub node_path: String,
    pub hub_port: u16,
    pub daemon_port: Option<u16>,
    pub token: Option<String>,
    pub entry_path: Option<String>,
    pub platforms: Value,
    pub tools: Value,
}

/// `connectOnce`'s first half: the bootstrap's `start` (or `agent-start`),
/// which installs and starts the hub (and agent daemon) on the host.
pub(super) async fn start(
    config: &SshConfig,
    owner: &str,
    agent: bool,
) -> Result<Started, HostError> {
    let (stdout, _) = bootstrap(config, owner, if agent { "agent-start" } else { "start" }).await?;
    let reading = || HostError {
        step: "reading host endpoints".into(),
        cause: Box::new(Cause::Other),
    };
    let value: Value = serde_json::from_str(stdout.trim()).map_err(|_| reading())?;
    let port = |key: &str| {
        value[key]
            .as_u64()
            .and_then(|port| u16::try_from(port).ok())
    };
    let (Some(node_path), Some(hub_port)) = (value["nodePath"].as_str(), port("hubPort")) else {
        return Err(reading());
    };
    if !value["platforms"].is_array() || !value["helpers"].is_object() {
        return Err(reading());
    }
    Ok(Started {
        node_path: node_path.to_owned(),
        hub_port,
        daemon_port: port("daemonPort"),
        token: value["token"].as_str().map(str::to_owned),
        entry_path: value["entryPath"].as_str().map(str::to_owned),
        platforms: value["platforms"].clone(),
        tools: value["tools"].clone(),
    })
}

/// The `ssh -L` connection that carries a host's hub (and agent daemon) here.
pub(super) struct Tunnel {
    pub child: tokio::process::Child,
    /// Held so the remote `cat` sees EOF, and ssh exits, when this server goes.
    _stdin: Option<tokio::process::ChildStdin>,
    /// The end of ssh's stderr, for a forward that never answers.
    pub stderr: Arc<std::sync::Mutex<String>>,
}

impl Tunnel {
    pub fn alive(&mut self) -> bool {
        matches!(self.child.try_wait(), Ok(None))
    }
}

fn host_error(step: &str, message: impl Into<String>) -> HostError {
    let _ = message.into();
    HostError {
        step: step.to_owned(),
        cause: Box::new(Cause::Other),
    }
}

/// `net.reserveLoopbackPort`.
fn reserve_port(step: &str) -> Result<u16, HostError> {
    std::net::TcpListener::bind(("127.0.0.1", 0))
        .and_then(|listener| listener.local_addr())
        .map(|address| address.port())
        .map_err(|error| host_error(step, error.to_string()))
}

/// `connectOnce`'s second half: forwards the host's ports to fresh loopback
/// ports here and waits for them to answer.
pub(super) async fn open_tunnel(
    config: &SshConfig,
    started: &Started,
) -> Result<(Tunnel, u16, u16), HostError> {
    let hub_port = reserve_port("reserving hub port")?;
    let daemon_port = reserve_port("reserving daemon port")?;
    let mut args = base_ssh_args(config.port);
    args.extend(config.identity_args());
    args.extend(
        [
            "-o",
            "ExitOnForwardFailure=yes",
            // Multiplexed clients exit after handing forwards to the master; own this connection.
            "-o",
            "ControlMaster=no",
            "-o",
            "ControlPath=none",
            "-o",
            "ControlPersist=no",
            "-o",
            "ServerAliveInterval=10",
            "-o",
            "ServerAliveCountMax=3",
            "-T",
            "-L",
        ]
        .map(String::from),
    );
    args.push(format!(
        "127.0.0.1:{hub_port}:127.0.0.1:{}",
        started.hub_port
    ));
    if let Some(remote) = started.daemon_port {
        args.push("-L".into());
        args.push(format!("127.0.0.1:{daemon_port}:127.0.0.1:{remote}"));
    }
    args.push(config.target.clone());
    // The server holds the only write end of this stdin, so when it exits for any reason the
    // remote `cat` sees EOF and ssh exits once its forwarded connections close.
    args.extend([
        "sh".into(),
        "-c".into(),
        quote_remote_arg("exec cat >/dev/null"),
    ]);
    let mut child = crate::login_shell::tokio_command("ssh")
        .args(&args)
        .stdin(Stdio::piped())
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .kill_on_drop(true)
        .spawn()
        .map_err(|error| host_error("forwarding ports", error.to_string()))?;
    let stdin = child.stdin.take();
    let stderr = Arc::new(std::sync::Mutex::new(String::new()));
    if let Some(mut pipe) = child.stderr.take() {
        let stderr = stderr.clone();
        tokio::spawn(async move {
            use tokio::io::AsyncReadExt;
            let mut buffer = [0u8; 4096];
            while let Ok(read) = pipe.read(&mut buffer).await {
                if read == 0 {
                    break;
                }
                let mut tail = stderr.lock().unwrap();
                tail.push_str(&String::from_utf8_lossy(&buffer[..read]));
                let chars: Vec<char> = tail.chars().collect();
                if chars.len() > 2000 {
                    *tail = chars[chars.len() - 2000..].iter().collect();
                }
            }
        });
    }
    let tunnel = Tunnel {
        child,
        _stdin: stdin,
        stderr,
    };
    let mut endpoints = vec![(format!("http://127.0.0.1:{hub_port}"), "/readyz")];
    if started.daemon_port.is_some() && started.token.is_some() && started.entry_path.is_some() {
        endpoints.push((format!("http://127.0.0.1:{daemon_port}"), "/health"));
    }
    for (base, route) in endpoints {
        wait_ready(&base, route, &tunnel.stderr).await?;
    }
    Ok((tunnel, hub_port, daemon_port))
}

/// `waitForHttpReady`: 15 seconds of probes, 100 ms apart.
async fn wait_ready(
    base: &str,
    route: &str,
    stderr: &std::sync::Mutex<String>,
) -> Result<(), HostError> {
    let client = reqwest::Client::builder()
        .no_proxy()
        .timeout(Duration::from_secs(1))
        .build()
        .unwrap();
    let deadline = tokio::time::Instant::now() + Duration::from_secs(15);
    loop {
        if let Ok(response) = client.get(format!("{base}{route}")).send().await {
            if response.status().is_success() {
                return Ok(());
            }
        }
        if tokio::time::Instant::now() >= deadline {
            let tail = stderr.lock().unwrap().clone();
            return Err(host_error(
                "waiting for SSH forward",
                if tail.is_empty() {
                    "Forwarded endpoint did not answer.".to_owned()
                } else {
                    tail
                },
            ));
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
}

/// `deviceToolInstallMessage`.
pub(super) fn install_message(name: &str, tool: &Value) -> String {
    if !tool.is_object() {
        return format!("Installing {name}…");
    }
    let required = tool["requiredVersion"].as_str().unwrap_or_default();
    let installed: Vec<&str> = tool["installedVersions"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .collect();
    let numeric = |version: &str| -> Vec<u64> {
        version
            .split(|c: char| !c.is_ascii_digit())
            .filter(|part| !part.is_empty())
            .map(|part| part.parse().unwrap_or(0))
            .collect()
    };
    let previous = tool["runningVersion"].as_str().or_else(|| {
        installed
            .iter()
            .copied()
            .max_by(|a, b| numeric(a).cmp(&numeric(b)))
    });
    match previous {
        Some(previous) if !installed.contains(&required) => {
            format!("Updating {name} from {previous} to {required}…")
        }
        _ => format!("Installing {name} {required}…"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fills_the_reference_bootstrap() {
        let script = bootstrap_script("abc", "probe");
        assert!(script.starts_with("\nconst owner = \"abc\";\nconst mode = \"probe\";\n"));
        assert!(!script.contains("{{"));
        assert!(environment().starts_with("export PATH=\"$HOME/.local/bin:"));
    }

    #[test]
    fn quotes_and_explains_like_the_reference() {
        assert_eq!(quote_remote_arg("it's"), "'it'\"'\"'s'");
        let config = SshConfig {
            id: "mac".into(),
            label: "Mac".into(),
            target: "mac.example".into(),
            port: Some(2222),
            identity_file: None,
        };
        let failed = |code, stderr: &str| HostError {
            step: "probe".into(),
            cause: Box::new(Cause::Ssh(SshCommandError {
                exit_code: Some(code),
                stdout: String::new(),
                stderr: stderr.into(),
                message: String::new(),
            })),
        };
        let explained = explain_connect(
            &config,
            failed(
                255,
                "ssh: Could not resolve hostname mac.example: Name or service not known\r\n",
            ),
        );
        assert_eq!(
            probe_failure_message(&explained).unwrap(),
            "Could not resolve the host name mac.example from the machine running this T3 Code server: ssh: Could not resolve hostname mac.example: Name or service not known."
        );
        assert_eq!(
            probe_failure_message(&failed(1, &format!("{NODE_MISSING}\n"))).unwrap(),
            "Connected over SSH, but Node is not on this host's PATH for non-interactive SSH commands."
        );
        assert_eq!(
            probe_failure_message(&failed(3, "")).unwrap(),
            "Connected over SSH, but the device host check failed (exit code 3)."
        );
        assert_eq!(
            probe_failure_message(&failed(255, "")).unwrap(),
            "Could not connect to this host over SSH."
        );
    }
}
